package edu.smartlibrary.repo;
import edu.smartlibrary.model.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*;
public interface UserRepository extends JpaRepository<AppUser,Long>{Optional<AppUser> findByEmailIgnoreCase(String email);boolean existsByEmailIgnoreCase(String email);long countByRole(Role role);@Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select u from AppUser u where u.id=:id") Optional<AppUser> lockById(@Param("id") Long id);}
